import axios from 'axios';

const API_KEY = process.env.REACT_APP_WEATHER_KEY;
console.log('Clé API utilisée :', API_KEY);

export const fetchWeather = async (lat, lon) => {
  const res = await axios.get('https://api.openweathermap.org/data/2.5/weather', {
    params: {
      lat,
      lon,
      appid: API_KEY,
      units: 'metric',
      lang: 'fr'
    }
  });
  return res.data;
};

export const fetchUVIndex = async (lat, lon) => {
  const response = await fetch(
    `https://api.openweathermap.org/data/2.5/onecall?lat=${lat}&lon=${lon}&exclude=hourly,daily,minutely,alerts&appid=${API_KEY}&units=metric`
  );
  const data = await response.json();
  return data.current.uvi;
};

export const fetchForecast = async (lat, lon) => {
  const res = await axios.get('https://api.openweathermap.org/data/2.5/forecast', {
    params: {
      lat,
      lon,
      appid: API_KEY,
      units: 'metric',
      lang: 'fr'
    }
  });
  return res.data;
};

// Stockage temporaire en mémoire (à remplacer par une vraie BDD)
let users = [];

export default function handler(req, res) {
  if (req.method === 'POST') {
    const { nom, email, password } = req.body;

    // Validation simple côté serveur
    if (!nom || !email || !password) {
      return res.status(400).json({ message: 'Tous les champs sont requis.' });
    }

    // Vérifier si l'email existe déjà
    const existingUser = users.find((user) => user.email === email);
    if (existingUser) {
      return res.status(409).json({ message: 'Un compte avec cet email existe déjà.' });
    }

    // Ici, on devrais hasher le mot de passe avant de le stocker (ex: bcrypt)
    // Pour la, on le stocke tel quel (a eviter en prod !)

    users.push({ nom, email, password });

    return res.status(201).json({ message: 'Compte créé avec succès.' });
  } else {
    res.setHeader('Allow', ['POST']);
    res.status(405).end(`Méthode ${req.method} non autorisée`);
  }
}
